 "{n} 公里 {dir}": "{dir} {n} km",
 "。抖音/微博/微信互动量需开放平台密钥且条款禁止抓取，故本页按「关键词命中数」排序，不展示热度值与参与量。": ". 더우인/웨이보/웨이신의 인터랙션량은 오픈 플랫폼 키가 필요하고 약관상 수집이 금지되어, 이 페이지는 '키워드 적중 수' 기준으로 정렬하며 열기 수치와 참여량은 표시하지 않습니다.",
 "全国底图 · 聚焦山东 · 各市 A 级景区数量热力（普查口径）+ 重点监测景点客流点位（圆点按景区等级着色）；点圆点看客流画像，单击地市切换分析范围并细分县区": "전국 베이스맵 · 산둥 집중 · 시별 A급 관광지 수 히트맵(전수조사 기준) + 중점 모니터링 관광지 방문객 지점(점 색상은 관광지 등급별); 점을 클릭하면 방문객 프로필, 지급시를 클릭하면 분석 범위 전환 및 현·구 세분화",
 "全国底图 · 聚焦山东 · 各市按固定彩色区分、五颜六色（颜色只作区分，范围外地市灰显，数量见图上数字）+ 收录美食碗形标（按类别着色）；点碗形标定位到所属县区，单击地市切换分析范围并细分县区": "전국 베이스맵 · 산둥 집중 · 시별 고정 색상으로 다채롭게 구분(색상은 구분용일 뿐, 범위 밖 지급시는 회색 표시, 수량은 지도 숫자 참조) + 수록 음식 사발 표시(카테고리별 색상); 사발 표시를 클릭하면 소속 현·구로 이동, 지급시를 클릭하면 분석 범위 전환 및 현·구 세분화",
 "全国底图 · 聚焦山东 · 各市自然保护区数量热力 + 保护区叶形标（按等级着色）与物种监测点；点叶形标看保护区详情，单击地市切换分析范围并细分县区": "전국 베이스맵 · 산둥 집중 · 시별 자연보호구 수 히트맵 + 보호구 잎 모양 표시(등급별 색상)와 종 모니터링 지점; 잎 모양 표시를 클릭하면 보호구 상세, 지급시를 클릭하면 분석 범위 전환 및 현·구 세분화",
 "全国底图 · 聚焦山东省 · 颜色越暖表示旅游热度越高 · 单位：万人次 · 统计周期：近30日": "전국 베이스맵 · 산둥성 집중 · 색이 따뜻할수록 관광 열기 높음 · 단위: 만 명 · 집계 주기: 최근 30일",
 "叶形标 = 保护区（按等级着色）；圆环 = 物种监测点（与保护区同址布设，按物种等级着色）": "잎 모양 표시 = 보호구(등급별 색상); 원형 링 = 종 모니터링 지점(보호구와 동일 위치에 설치, 종 등급별 색상)",
 "按名录「申报地区」归属到县区，圆点大小 = 项目数（仅统计能归到县区的项目）；点左侧清单里的项目可定位到该县区。": "명부 '신청 지역' 기준 현·구에 귀속, 점 크기 = 프로젝트 수(현·구에 귀속 가능한 프로젝트만 집계); 왼쪽 목록의 프로젝트를 클릭하면 해당 현·구로 이동할 수 있습니다.",
 "清单为平台整理的山东饮食文化条目（鲁菜名菜 / 地方名吃 / 地理标志农产品 / 非遗美食），": "목록은 플랫폼이 정리한 산둥 음식 문화 항목(루차이 명요리/향토 명물/지리적 표시 농산물/무형유산 음식),",
 "游客整体评价较好，重点集中在景观体验、服务设施与交通便利性；高峰时段存在排队拥堵反馈。": "관광객 전반 평가는 양호하며, 경관 체험·서비스 시설·교통 편의성에 집중되어 있습니다; 혼잡 시간대에는 대기·정체 피드백이 있습니다.",
 "范围内灾害风险指数 = 气象实况 + 近十年地震活动（两项为真实抓取数据）+ 地灾隐患 / 人流预警 / 水情监测（演示）": "범위 내 재해 리스크 지수 = 기상 실황 + 최근 10년 지진 활동(앞의 두 항목은 실제 수집 데이터) + 지질재해 위험/인파 경보/수문 모니터링(데모)",
 "范围内（{scope}）近 {n} 条报道中，词表判定为负面的 {negative} 条（{share}%），未达到分级阈值（<3% 且 <2 条）": "범위 내({scope}) 최근 {n}건 보도 중 어휘 목록에서 부정으로 판정된 {negative}건({share}%), 등급 임계값에 미도달(<3% 및 <2건)",
 "范围内（{scope}）近 {n} 条报道中，词表判定为负面的 {negative} 条（{share}%），达到中等级阈值（≥8% 或 ≥4 条）": "범위 내({scope}) 최근 {n}건 보도 중 어휘 목록에서 부정으로 판정된 {negative}건({share}%), 중간 등급 임계값에 도달(≥8% 또는 ≥4건)",
 "范围内（{scope}）近 {n} 条报道中，词表判定为负面的 {negative} 条（{share}%），达到偏低阈值（≥3% 或 ≥2 条）": "범위 내({scope}) 최근 {n}건 보도 중 어휘 목록에서 부정으로 판정된 {negative}건({share}%), 낮은 편 임계값에 도달(≥3% 또는 ≥2건)",
 "范围内（{scope}）近 {n} 条报道中，词表判定为负面的 {negative} 条（{share}%），达到高等级阈值（≥15% 或 ≥8 条）": "범위 내({scope}) 최근 {n}건 보도 중 어휘 목록에서 부정으로 판정된 {negative}건({share}%), 높은 등급 임계값에 도달(≥15% 또는 ≥8건)",
