 "排查景区低洼路段与山洪沟道，涉水项目视情关停，必要时组织游客转移": "관광지 저지대 도로와 산지 홍수 배수로 점검, 물놀이 시설은 상황에 따라 운영 중지, 필요 시 관광객 대피 조치",
