 "晴间多云": "구름 조금",
 "暂停户外大型活动与高空项目，疏导游客进入室内场馆避险": "야외 대형 행사와 고공 시설 운영 중단, 관광객을 실내 시설로 대피 유도",
 "暴雨：日累计降水 ≥50mm 蓝、≥100mm 黄、≥150mm 橙、≥200mm 红": "폭우: 일 누적 강수량 ≥50mm 청색, ≥100mm 황색, ≥150mm 주황색, ≥200mm 적색",
