 "正北": "정북",
 "正南": "정남",
 "正西": "정서",
 "毛毛雨": "이슬비",
 "点击缩略图放大查看（支持键盘 ← → 切图、Esc 关闭）": "썸네일을 클릭해 확대 보기(키보드 ← → 이미지 전환, Esc 닫기)",
 "码头、索道与临水临崖路段视情暂停，加强交通引导与能见度提示": "부두, 삭도, 물가와 절벽 인접 도로는 상황에 따라 통제, 교통 안내와 가시거리 안내 강화",
 "索道、游船等户外项目视情关停，加固围挡与临时设施，疏导高空区域游客": "삭도, 유람선 등 야외 시설은 상황에 따라 운영 중지, 울타리와 임시 시설 보강, 고공 구역 관광객 대피 유도",
 "红色 · 高": "적색 · 높음",
 "蓝色 · 平稳": "청색 · 안정",
 "西北": "북서",
 "西南": "남서",
 "西南风": "남서풍",
 "西西北": "서북서",
 "西西南": "서남서",
 "西风": "서풍",
