 "芦苇": "갈대",
 "菏泽市自然资源和规划局": "허저시 자연자원계획국",
 "黄河三角洲生态红线": "황허 삼각주 생태 적색선",
 "南四湖生态红线": "난쓰후 생태 적색선",
 "济南三大名胜之首，趵突泉居七十二名泉之冠，三窟并发、四季恒温，素有「天下第一泉」之称。": "지난 3대 명승의 으뜸으로, 바오투취안은 72명천 중 최고이며 세 개의 물줄기가 함께 솟고 사계절 수온이 일정해 예로부터 '천하제일천'이라 불립니다.",
 "济南本地": "지난 현지",
 "五岳之首，世界文化与自然双遗产，主峰玉皇顶海拔 1545 米，历代帝王封禅告祭之地。": "오악의 으뜸이자 세계 문화·자연 복합유산으로, 주봉 위황딩의 해발은 1545 m이며 역대 제왕이 봉선 제사를 올린 곳입니다.",
 "孔庙、孔府、孔林合称「三孔」，世界文化遗产，是儒家文化最完整的实物遗存。": "공묘·공부·공림을 합쳐 '삼공'이라 하며, 세계문화유산으로 유교 문화가 가장 완전하게 남은 실물 유산입니다.",
 "山西": "산시",
 "黄河入海处的新生湿地，芦花飞雪、河海交汇，是东方白鹳、黑嘴鸥等珍禽的繁殖地。": "황허가 바다로 들어가는 곳의 신생 습지로, 갈대꽃이 눈처럼 날리고 강과 바다가 만나며, 황새·검은머리갈매기 등 진귀한 새의 번식지입니다.",
 "由济南众泉汇流而成的天然湖泊，「四面荷花三面柳，一城山色半城湖」即咏此处。": "지난의 여러 샘물이 모여 이루어진 천연 호수로, '사방은 연꽃, 삼면은 버들, 온 성이 산색이고 성의 절반이 호수'라는 시구가 이곳을 노래합니다.",
 "济南三大名胜之一，古称历山，隋代崖壁造像千余尊，登顶可俯瞰泉城全景。": "지난 3대 명승 중 하나로 옛 이름은 리산이며, 수나라 때 조성된 천여 존의 마애불이 있고, 정상에 오르면 샘의 도시 전경을 내려다볼 수 있습니다.",
 "南四湖中面积最大的湖泊湿地，荷花芦苇连片，也是南水北调东线的重要调蓄湖泊。": "난쓰후에서 면적이 가장 큰 호수 습지로 연꽃과 갈대가 이어지며, 남수북조 동선의 중요한 조절 저수지이기도 합니다.",
 "《水浒传》故事发生地，梁山寨、忠义堂等遗迹尚存，是水浒文化旅游的核心景区。": "『수호전』 이야기의 무대이며 량산채·충의당 등 유적이 남아 있는, 수호전 문화관광의 핵심 관광지입니다.",
 "有「旱码头」之称的周村大街，保存完好的明清商业街市，瑞蚨祥等老字号的发源地。": "'마른 항구'라 불리는 저우춘 거리로, 명·청 시대 상업 거리가 잘 보존되어 있으며 루이푸샹 등 노포의 발상지입니다.",
 "以《孙子兵法》为主题的仿古建筑群，位于兵圣孙武故里惠民县，是鲁北文旅地标。": "『손자병법』을 주제로 한 고풍 건축군으로, 병성 손무의 고향 후이민현에 있는 루베이 문화관광 랜드마크입니다.",
