 "枣庄石榴": "짜오좡 석류",
 "籽粒晶亮、酸甜适口": "알갱이가 맑고 영롱하며 새콤달콤해 입에 맞음",
 "鲜食石榴": "생식 석류",
 "石榴汁": "석류주스",
 "石榴酒": "석류주",
 "峄城万亩榴园有 2000 余年栽培史，石榴籽大汁多、酸甜适中，是运河边的「石榴之乡」。": "이청의 만 무 석류원은 2000여 년의 재배 역사가 있으며, 석류 알이 크고 과즙이 많으며 새콤달콤함이 알맞은 운하 변의 '석류의 고장'입니다.",
